"""One-time isolated native direct-reinforcement port; launches no GPU work."""
from pathlib import Path
ROOT=Path(__file__).parent;branch=ROOT/'rl_exposure_direct_native_trial'
def replace(text,old,new):
    if text.count(old)!=1:raise AssertionError(f'Expected unique source fragment: {old[:90]}')
    return text.replace(old,new)
p=branch/'text_policy.py';s=p.read_text();s=s.replace("'exposure_text_v1'","'exposure_sharpe_text_v1'");p.write_text(s)
p=branch/'exposure_prompt.py';s=p.read_text()
s=replace(s,'Seek net returns with moderate risk aversion. Daily utility is net return minus 1.5 times its square, using decimal returns.','Seek high net risk-adjusted returns measured by the Sharpe ratio, with zero cash interest and zero risk-free benchmark.')
p.write_text(s)
p=branch/'text_gate.py';s=p.read_text();s=replace(s,"Path('../checks/exposure_native_soft_gate')","Path('../checks/exposure_native_direct_gate')");p.write_text(s)
p=branch/'train_direct.py';s=p.read_text()
s=replace(s,'from numeric_policy import NumericPolicy,state_digest','from text_policy import TextPolicy')
s=replace(s,'from train import seed_everything','from train import seed_everything,lora_digest')
s=s.replace("tensor(obs,'cpu')","tensor(obs,'cuda')")
s=s.replace('torch.tensor(LEVELS)','torch.as_tensor(LEVELS,device=p.device)')
s=s.replace('p.numpy()','p.cpu().numpy()')
s=s.replace('p.detach().numpy()','p.detach().cpu().numpy()')
s=s.replace("normalized_probabilities(policy,obs).numpy()","normalized_probabilities(policy,obs).cpu().numpy()")
s=replace(s,"if torch.cuda.is_available():raise RuntimeError('CPU control requires hidden CUDA')","if not torch.cuda.is_available():raise RuntimeError('Native training requires CUDA')")
s=replace(s,'policy=NumericPolicy(train.env.tickers);optimizer=torch.optim.AdamW(policy.parameters(),lr=.001,weight_decay=0)',"policy=TextPolicy(train.env.tickers)\n    params=[p for p in policy.parameters() if p.requires_grad]\n    if any('lora_' not in n for n,p in policy.named_parameters() if p.requires_grad):raise AssertionError('Only LoRA trains')\n    optimizer=torch.optim.AdamW([{'params':[p for n,p in policy.named_parameters() if p.requires_grad and '.lm_head.' not in n],'lr':1e-5},\n        {'params':[p for n,p in policy.named_parameters() if p.requires_grad and '.lm_head.' in n],'lr':3e-4}],weight_decay=0)")
s=s.replace('state_digest(policy)','lora_digest(policy)')
s=s.replace('initial_policy_sha256','initial_lora_sha256').replace('final_policy_sha256','final_lora_sha256')
s=replace(s,"'execution':{'device':'cpu','cuda_hidden':True,'threads':2}","'execution':{'device':'cuda','active_decoder_dtype':'fp32','threads':2},'adapter_scope':'attention_readout_v1','prompt_schema':'exposure_sharpe_text_v1'")
s=replace(s,"'.01 mean KL to initial uniform policy, on current observed states'","'.01 mean KL to exact adapter-disabled initial policy on the same current observed states'")
s=replace(s,"'AdamW .001, one update per fresh pair of segments, norm cap 1, post-update mean KL ceiling .03'","'AdamW attention LoRA 1e-5, original readout LoRA 3e-4; one update per fresh segment pair; norm cap 1; post-update mean KL ceiling .03'")
s=s.replace("evaluate(policy,val,'cpu')","evaluate(policy,val,'cuda')").replace("evaluate(policy,dev,'cpu')","evaluate(policy,dev,'cuda')")
s=replace(s,"'torch_rng':torch.get_rng_state()","'torch_rng':torch.get_rng_state(),'cuda_rng':torch.cuda.get_rng_state_all()")
s=replace(s,"wait_for_compute_window();p=normalized_probabilities(policy,obs)\n            error=", "wait_for_compute_window()\n            with torch.no_grad(),policy.shared.model.disable_adapter():reference=normalized_probabilities(policy,obs).detach()\n            p=normalized_probabilities(policy,obs)\n            error=")
s=replace(s,'kl=(p*torch.log(p/.25)).sum()','kl=(p*(torch.log(p)-torch.log(reference))).sum()')
s=replace(s,'exposure*coefficient.detach()','exposure*coefficient.detach().to(p.device)')
s=replace(s,'clip_grad_norm_(policy.parameters(),1.','clip_grad_norm_(params,1.')
p.write_text(s)
print('Prepared native direct-reinforcement source; no model loaded or training launched.')
